import {
  acquireWriterLease,
  prepareApplicationStateRoot,
} from '@happyvertical/smrt-app-runtime';
import { createSmrtSvelteKitRuntime } from '@happyvertical/smrt-app-runtime/sveltekit';
import { ObjectRegistry, type SmrtObject } from '@happyvertical/smrt-core';

// Generated by the smrt() Vite plugin on every dev/build run (gitignored).
import './smrt-register.js';

/** Local profile: SQLite outside the checkout, single owner, signed session. */
export const runtime = createSmrtSvelteKitRuntime({
  acquireWriterLease: (context) =>
    acquireWriterLease(prepareApplicationStateRoot(context), {
      operationInstance: process.env.SMRT_OPERATION_INSTANCE,
    }),
});

/** The generated `/api/*` routes import this; call it per request. */
export function getCollection<T extends SmrtObject>(className: string) {
  return ObjectRegistry.getCollection<T>(
    className,
    runtime.classOptions(className),
  );
}
